window.BOOK = [{"chapter": 1, "chapterTitle": "An Unscheduled Adventure", "paragraphs": ["The first sign of trouble was that Molly's map had acquired a puddle.", "This was unusual for a number of reasons. It had not rained in her bedroom. Jim had not watered the carpet. And maps, in Molly's experience, generally preferred to describe damp places rather than become them.", "She put one paw beside the folded leaf beneath her bed.", "Salt water.", "Molly knew that smell. She lived near the sea, where practically everything acquired a small amount of it eventually, including biscuits if you were not careful on the promenade.", "But this water smelled deeper and colder than the sea outside.", "She unfolded the silver-green leaf.", "Pip had drawn it for her after their adventure in Moonflower Wood. The library, the Singing Bridge and Luma's quiet bank sat neatly along a familiar path.", "Now a fourth place appeared in the corner.", "A little black door.", "Molly watched a thin silver line draw itself towards it.", "Underneath, in handwriting that was not Pip's, appeared three words.", "YOU ARE EXPECTED.", "Molly adjusted the cream bow above her rainbow fringe.", "“That's very presumptuous,” she told the map.", "From downstairs, Jim called, “Walk?”", "Her tail rose.", "Some invitations were considerably easier to accept than others."]}, {"chapter": 1, "chapterTitle": "An Unscheduled Adventure", "paragraphs": ["Molly carried the map in her neckerchief.", "Jim noticed the bulge, inspected it briefly and said, “Taking your paperwork?”", "She wagged.", "He had become surprisingly relaxed about her possessions. Since the previous adventure, she had collected a perfectly respectable stick, a silver-green leaf and a plain cream bow that had once been rainbow-coloured.", "Jim assumed the last item had met a washing accident.", "Molly had decided there was little point arguing with a person who thought all important explanations began with somebody's washing machine.", "In the park, the ash tree stood beside the fountain. Ordinary roots, ordinary leaves. A gull watched the path with the focused interest of a professional sandwich inspector.", "Then the moonflower between the roots opened.", "Pip appeared beneath it, green satchel crooked across his shoulder.", "“Oh, good,” he said. “You've received my message.”", "Molly took out the map.", "“This?”", "Pip stared at the black door.", "“That isn't my message.”", "“What was yours?”", "“Please bring yourself and, if convenient, an oatcake.”", "Molly looked towards Jim. He had stopped to tie a shoelace.", "Around him, the folding minute grew still.", "“Right,” she said. “We'd better compare our post.”"]}, {"chapter": 1, "chapterTitle": "An Unscheduled Adventure", "paragraphs": ["The gate smelled exactly as Molly remembered: moss, moonflowers and a small amount of astonishing possibility.", "Beyond it, Moonflower Wood was beautifully itself. Green ferns, yellow lanterns, purple shadows. The colours she and her friends had helped return still moved through the rootwater.", "The Singing Bridge stood whole again, though somebody had sensibly added a notice about crossing one at a time.", "Pip saw Molly looking.", "“Juniper calls it his bridge.”", "“Does it agree?”", "“It hasn't complained where we can hear.”", "Molly took a deep breath. She was pleased to be back. She was also aware that pleasure could make a mysterious black door look more reasonable than it deserved.", "“How long do I have?” she asked.", "“The fold lasts until moonset. Same as before. Luma checked.”", "“And what's wrong this time?”", "Pip took a letter from his bag.", "It was addressed to his aunt. The words had begun to move. Her name remained steady, but the directions underneath kept changing.", "Hazel Path.", "East Orchard.", "The Third Turning After Yesterday.", "Molly sniffed the paper.", "Fresh ink. Old dust.", "No smell of hazel at all.", "Pip swallowed.", "“People are losing the way to places they know.”"]}, {"chapter": 1, "chapterTitle": "An Unscheduled Adventure", "paragraphs": ["At the first junction they found Fern the hedgehog standing where her potting shed ought to have been.", "The shed was still there. Molly could see its roof beyond a hedge. But the path that usually reached it now curved away and returned to the same junction.", "Fern had made six attempts. Her barrow contained seedlings, a watering can and the beginnings of a bad temper.", "“I've lived beside that shed for years,” she said. “Apparently it wants a more formal introduction.”", "Molly followed the path for a few steps. The air ahead smelled of cut grass, then suddenly of paper.", "She stopped before the bend.", "“That's not the right way.”", "“It looks right,” Pip said.", "“Yes. That's what makes it rude.”", "They backed up and examined the hedge. Beneath its lowest branches lay the narrow groove Fern's wheel had made on hundreds of ordinary mornings.", "Molly squeezed underneath.", "The true path smelled of earth, seedlings and hedgehog. It reached the shed in eleven sensible paces.", "Fern followed, pushing her barrow through the gap.", "“Good nose,” she said.", "“Several years of practice.”", "On the misleading bend, a silver line gleamed once and vanished beneath the grass."]}, {"chapter": 1, "chapterTitle": "An Unscheduled Adventure", "paragraphs": ["Bramble was waiting at the Leaf Library with three undelivered letters, two unsettled visitors and a cup of tea he had forgotten to drink.", "“That,” Molly said, “is how trouble usually starts.”", "He looked at the cup.", "“Quite.”", "The visitors were a shrew who could not find the baker and a beetle who had reached the baker but could not explain how. Pip spread Molly's map on the desk.", "Bramble examined the black door through a magnifying glass.", "“Not one of Pip's marks. Not any authorised path symbol I know.”", "“And the puddle?”", "“Worrying.”", "“I'd hoped for something more librarian-shaped.”", "“Deeply worrying.”", "A bell beside the window should have rung to announce the beginning of the final lantern-hour before midnight.", "It did not.", "Bramble looked up sharply.", "From across the wood came an answering absence. No little bells along the paths. No silver note from the Heartwell.", "Pip's ears lowered.", "“The Waybell?”", "Bramble nodded.", "“The smaller bells follow it.”", "Molly looked at the changing directions on the letters.", "“Then I think,” she said, “we should find out who's keeping the time.”"]}, {"chapter": 2, "chapterTitle": "Shortcuts at Sensible Prices", "paragraphs": ["Quill's new stall occupied a particularly comfortable corner of the Lantern Market.", "He still sold empty jars, which Molly approved of. He also sold labels, ribbons and a selection of handsome little maps under a sign reading SHORTCUTS AT SENSIBLE PRICES.", "Molly read the sign twice.", "Quill folded his wings.", "“Before you say anything, the prices really are sensible.”", "“Are the shortcuts?”", "He opened his beak, then closed it.", "The maps had come from a travelling collector who called himself Mr Vellum. He had offered Quill a commission for distributing them, along with free access to an apparently remarkable delivery route.", "“How remarkable?” Bramble asked.", "“You can reach the east orchard without passing the west orchard.”", "“That is normally how east works,” Molly said.", "Quill produced the collector's agreement. It was written in fine, perfectly regular ink.", "Temporary route improvements. Borrowed directions held until the Waybell's next midnight chime.", "Bramble ran a claw along the last line.", "“And if the bell doesn't ring?”", "Quill's feathers lost some of their confidence.", "“I didn't ask.”", "From a paper map beside them came the faint sound of a latch closing."]}, {"chapter": 2, "chapterTitle": "Shortcuts at Sensible Prices", "paragraphs": ["The collector had not asked people to sell their homes.", "He had asked to borrow their directions.", "A map of the garden. The quickest route to a friend's door. A delivery note showing a particular side entrance. Ordinary things that seemed too small to worry about.", "In return, he supplied a shorter, tidier route.", "“The old maps have gone where?” Molly asked.", "“His travelling office,” Quill said. “He said he'd compare them, then return them at midnight.”", "Pip looked at the agreement.", "“What happens to a borrowed path if the directions aren't returned?”", "Bramble's expression became extremely librarian-shaped.", "“Eventually the new route takes priority. The old way grows difficult to remember.”", "“Fern's shed.”", "“Yes.”", "Molly looked around the market. Squirrels were laughing at a map of a bakery route that took three steps instead of thirty. A vole was explaining that the collector had saved him hours.", "The improvements were not all imaginary.", "That made the trouble harder to untangle.", "Quill shifted from one foot to the other.", "“Shall I take the sign down?”", "“Yes,” Molly said. “Then help us find everyone who bought a map.”", "For once he did not argue about lost business."]}, {"chapter": 2, "chapterTitle": "Shortcuts at Sensible Prices", "paragraphs": ["Nettle arrived from the lower channels carrying a wet notebook.", "“Someone has redirected my inspection route,” he said. “It now reaches an excellent view of a wall.”", "Molly asked whether he had borrowed a shortcut.", "“No. But the shortcut crosses my route. The map seems to think the rest of it is untidy.”", "Bramble examined the collector's print again. The new paths were not merely joining the old ones. Where they overlapped, the old ones were being folded underneath.", "“Can you unfold them?” Pip asked.", "“Not by guessing. Someone might be on the folded part.”", "Nettle looked towards the river.", "“I heard somebody calling near the paper bridge.”", "“The what?” Molly said.", "“It wasn't there yesterday.”", "Bramble put three letters into his bag and selected a lantern that had recently been checked.", "Molly noticed the care he took.", "“No dramatic waving of sticks this time?” she asked.", "“I'm trying to learn.”", "Quill gathered the unsold maps. Nettle agreed to inspect the existing channels for changes. Fern would warn the market households and leave her old wheel tracks visible.", "Pip took Molly's map.", "The black door had grown a little wider."]}, {"chapter": 2, "chapterTitle": "Shortcuts at Sensible Prices", "paragraphs": ["Luma met them at the Heartwell's east bank.", "Her great silver wings rested loosely against her sides. The quiet path remained quiet. Somebody had left a small pot of flowers beside the bench, without attaching a request to it.", "Molly was glad to see that.", "Luma examined the silver line on the map.", "“Gate ink,” she said. “But it hasn't been invited into a real gate yet.”", "“What does that mean?”", "“Maps may describe a way. They cannot make someone welcome you through it. Not unless someone with the right to invite agrees.”", "Molly remembered the words beneath the door.", "YOU ARE EXPECTED.", "“Is that an invitation?”", "“No. It wants you to think one has already been made.”", "Pip put the map down as if it might bite.", "Luma's antenna touched the edge of the drawing.", "“The Waybell helps the paths recognise their proper names. Without it, borrowed routes can begin claiming more than they were offered.”", "“Can you find the bell?” Bramble asked.", "“I can follow its old note. Quietly.”", "Molly put on her sunglasses.", "“Then let's go and ask Mr Vellum a few reasonably uncomfortable questions.”"]}, {"chapter": 2, "chapterTitle": "Shortcuts at Sensible Prices", "paragraphs": ["They reached the river along a path that smelled increasingly of ink.", "The paper bridge curved between two alders. Its folded panels were printed with tiny fields, lanes and rivers. Light moved along every crease.", "Molly did not put a paw on it.", "On the far bank stood a fox made entirely of silver map paper.", "He was handsome in a way that seemed to have been carefully measured. Blue lines ran over his shoulders. His paws were folded from black-edged squares. His smile had sharp, precise corners.", "“Visitors,” he said. “How fortunate.”", "“Mr Vellum?” Bramble asked.", "“At your service.”", "“Are you?” Molly said.", "The fox looked down at her rainbow hair and cream bow.", "“Ah. The traveller.”", "She disliked the definite article.", "“Which traveller?”", "“The one whose map has learned a new road.”", "Pip tightened his grip on the leaf.", "Mr Vellum glanced at it with an interest he did not quite hide.", "Molly stayed on the ordinary bank.", "“Before anyone crosses anything,” she said, “we'd like to know why your customers can't find their sheds.”"]}, {"chapter": 3, "chapterTitle": "The Fox Made of Paper", "paragraphs": ["Mr Vellum looked wounded by the word customers.", "“I think of them as correspondents.”", "“Do they think of themselves as lost?” Molly asked.", "“Adjustments are occasionally unsettling.”", "“So are badly placed puddles. That doesn't make them improvements.”", "Bramble asked about the borrowed maps. Mr Vellum explained that he was preparing an Atlas of All Ways, in which every road would be clear, efficient and free of unnecessary turns.", "Pip's whiskers twitched.", "“Some turns are how you get somewhere.”", "“Only until a better way is drawn.”", "The fox invited them to his office beyond the bridge. They could inspect the maps there. He had tea, biscuits and a specialist interest in helping unusual travellers return home.", "Molly looked at the bridge.", "She could see its shape. She could smell paper, varnish and a trace of dust.", "She could not smell the bank on the other side.", "“What happens if I stop halfway?”", "“The route continues.”", "“That wasn't the question.”", "For a moment the fox's neat smile tightened.", "Luma moved beside Molly.", "“We'll take the ordinary crossing,” she said.", "Mr Vellum bowed.", "“Of course. If you can still find it.”"]}, {"chapter": 3, "chapterTitle": "The Fox Made of Paper", "paragraphs": ["The ordinary crossing stood twenty paces upstream.", "It had not vanished. It had become remarkably easy to overlook. Reeds leaned across the entrance, and a silver sign pointed elsewhere with excessive confidence.", "Molly put her nose to the ground.", "Mud. River mint. The old scent of a badger carrying too many books.", "“This way.”", "The real bridge was narrow but sound. They inspected it, crossed and approached Mr Vellum's office from the back.", "The office stood on wheels beneath a striped awning. It was made of folded doors, each opening onto a different shelf of maps. Paper birds slept along its roof.", "Mr Vellum was waiting with cups arranged on a small table.", "“You do prefer the scenic route.”", "“I prefer the route that can explain where its feet are,” Molly said.", "Pip almost smiled.", "Inside the nearest door, hundreds of borrowed maps hung from silver clips. Under each clip, the collector had written a new, shorter description.", "HOME VIA MARKET.", "GARDEN VIA OFFICE.", "RIVER VIA OFFICE.", "Molly looked at the last word repeating down the wall.", "A great many useful paths had begun leading through the fox."]}, {"chapter": 3, "chapterTitle": "The Fox Made of Paper", "paragraphs": ["Bramble asked for Fern's original garden map.", "Mr Vellum found it immediately. That might have been reassuring if he had not found it rather too immediately.", "“The borrowers may collect their property at the appointed chime,” he said.", "“The Waybell is missing.”", "“Then we must be patient.”", "Molly watched his black paper paws. One rested lightly against a locked drawer underneath the table.", "From inside came a tiny vibration.", "Not a sound. The feeling of a bell remembering it should have made one.", "She looked at Luma.", "The moth gave the smallest nod.", "“Did somebody lend you the Waybell?” Molly asked.", "Mr Vellum's tail folded into a sharper angle.", "“The bell was impeding the work.”", "“That sounds like a no.”", "“The wood will be easier to navigate without everybody insisting on their own particular way.”", "Pip took a step forward.", "“My aunt's way is particular because it goes to my aunt.”", "The fox looked at him with unexpected irritation.", "“Names,” he said, “make everything difficult.”", "Molly thought about a wood in which every home could be reached only by asking one collector's permission.", "Names were not the difficulty.", "They were the part he wanted to remove."]}, {"chapter": 3, "chapterTitle": "The Fox Made of Paper", "paragraphs": ["They did not seize the drawer.", "Molly wanted to. Her paws were quite certain about the usefulness of immediate action. But the office contained routes with people somewhere along them, and the fox's folded tail had settled across a delicate network of silver threads.", "Bramble asked what would happen if the office were damaged.", "“Misplaced roads can be difficult to recover,” Mr Vellum replied.", "It was the first completely straightforward thing he had said.", "Luma asked him to return the bell voluntarily.", "“No.”", "“Then we need an independent way to restore the paths,” Bramble said.", "Mr Vellum looked almost amused.", "“Independent of my atlas? Using what?”", "Pip started to speak. Molly touched his shoulder.", "“We'll let you know when we've checked.”", "They left the office along the real bank.", "Behind them, Mr Vellum called, “You will want the quickest way home eventually.”", "Molly did want it. That was what made his offer dangerous.", "She kept walking.", "Only when the office disappeared behind the alders did Pip whisper his idea.", "“The Star Room.”", "Bramble looked at him.", "“The old observatory?”", "“The stars don't go through Mr Vellum's office.”", "Molly grinned.", "“Good. I'd hate to see his commission.”"]}, {"chapter": 3, "chapterTitle": "The Fox Made of Paper", "paragraphs": ["On the way to the Star Room, they heard the calling Nettle had mentioned.", "It came from a small cottage beyond a turning that had folded itself into a neat paper fan.", "An elderly mole stood at the cottage window.", "“I'm Mrs Barley,” she called. “And I'd rather like somebody to explain where my front path has gone.”", "Her pantry was stocked. Her fire was safe. She was not in immediate danger. She was also effectively surrounded by directions that no longer led anywhere she recognised.", "Bramble told her what they knew.", "“Collector,” she said. “Yes. Very polite. Should have suspected that.”", "Molly asked whether she remembered walking the old route.", "“Course I do. Three stones, the fallen pear tree, then the bend where my nephew always drops his parcels.”", "Pip wrote it down.", "The paper fan loosened slightly when Mrs Barley described the pear tree.", "Everyone noticed.", "“Memory,” Pip whispered.", "“Walked memory,” Luma said. “A true map remembers an actual journey.”", "They left Mrs Barley a light, a packet of oatcakes and a promise to return with help.", "Not a guarantee.", "An intention made specific enough to be useful."]}, {"chapter": 4, "chapterTitle": "The Room Above the Leaves", "paragraphs": ["The Star Room occupied the highest branch of a hollow chestnut tree.", "Getting there involved a spiral stair, a small lift and a notice asking visitors not to lean on the sky.", "Molly read the notice.", "“Has somebody?”", "“Twice,” Bramble said. “Both complaints were difficult to classify.”", "Inside, a brass telescope pointed through an open section of roof. Leaf atlases lay on broad tables. Silver threads linked the ceiling to a model of the woodland paths.", "Luma dimmed the lantern.", "Actual stars appeared between the branches.", "Pip unrolled his aunt's old route beside Mrs Barley's description. Mr Vellum's silver lines tried to straighten both.", "Bramble placed a clear star chart over them.", "The silver lines hesitated.", "“Fixed references,” he said.", "“Fixed until they move,” Luma corrected.", "“Dependable references, then.”", "Molly put her paws on a cushion and watched the maps settle against the real sky.", "The fox could print a star.", "He could not persuade the actual one to report to his office.", "For the first time that evening, the changing directions stayed still long enough for Pip to measure them."]}, {"chapter": 4, "chapterTitle": "The Room Above the Leaves", "paragraphs": ["In the oldest atlas, Bramble found a note about the Waybell.", "Its midnight note did not command the paths. It called each borrowed way to remember who had walked and named it before.", "“If we retrieve the bell, will everything go back?” Molly asked.", "“Only if the old routes still have living anchors,” Luma said. “Remembered places. Real footsteps. Connections that haven't been completely folded away.”", "Mrs Barley's pear tree.", "Fern's wheel tracks.", "Nettle's inspection channel.", "All the unremarkable things Mr Vellum considered untidy.", "Pip examined Molly's map. The three original pictures remained clear. The new black door still shone in the corner, untouched by the star chart.", "“Why hasn't that settled?” he asked.", "Bramble looked through several volumes before answering.", "“I don't know.”", "Molly appreciated the answer and disliked it at exactly the same time.", "In a drawer beneath the telescope they found a maker's stamp: a little seven-pointed compass with one point shaped like a wave.", "The same stamp appeared beneath the black door.", "Bramble sat very still.", "“Alder,” he said.", "Pip looked up.", "“The mapmaker who never came back?”", "Molly's peace charm gave a small, cold touch against her chest."]}, {"chapter": 4, "chapterTitle": "The Room Above the Leaves", "paragraphs": ["Alder had mapped the earliest roads between Moonflower Wood and the places beyond it.", "He was a pine marten, Bramble said, patient about distances and impatient about chairs. He believed a map should help someone travel without pretending to own the journey.", "Years earlier, he had followed a route he called the Tide Road.", "No returning map had ever arrived.", "“Dead?” Molly asked quietly.", "“Missing,” Bramble said. “Those words aren't the same.”", "Luma's antennae moved over the compass stamp.", "“I remember him making little paper animals for the young ones.”", "“A fox?”", "“Among others.”", "Molly looked at the straight lines in the collector's printed directions.", "A created thing could outgrow its maker's purpose. She had no difficulty believing that. People gave dogs instructions about not climbing onto sofas, and the results were frequently disappointing.", "But Mr Vellum's connection to Alder did not explain what he wanted with her map.", "Bramble carefully copied the stamp.", "“One problem at a time,” he said.", "“Can they queue?” Molly asked.", "“They seldom do.”", "Below the Star Room, a path gave a soft rustle and folded itself into darkness."]}, {"chapter": 4, "chapterTitle": "The Room Above the Leaves", "paragraphs": ["Quill arrived through the open roof carrying a bundle of returned shortcut maps.", "“Everyone I could find,” he said. “I've told them to stay with their familiar places and stop following the silver arrows.”", "“Good,” Bramble said.", "The jackdaw put a second bundle on the table.", "“Also their old route descriptions.”", "Pip looked impressed.", "“I asked useful questions,” Quill said. “It was less unpleasant than expected.”", "One customer remembered a crooked gate. Another remembered the scent of wild garlic beside a bend. A family of rabbits remembered a low tunnel that never appeared on formal maps because it was embarrassing to the mayor's hat.", "The original routes began emerging under the shortcut lines.", "Pip marked their anchors against the star chart.", "“We could rebuild the connection before the bell rings,” he said. “Give the old paths something real to answer through.”", "“Then we still need the bell,” Luma said.", "Quill hesitated.", "“Mr Vellum has moved his office.”", "“Where?”", "The jackdaw pointed down.", "On the model of the wood, the collector's silver lines were drawing themselves towards one central place.", "The Milepost House.", "Exactly where every main path used to choose its own direction."]}, {"chapter": 4, "chapterTitle": "The Room Above the Leaves", "paragraphs": ["They made their plan under the stars.", "Nettle would check the true water channels and mark the routes Mr Vellum had covered. Fern would help households keep a familiar thing at each original turning. Quill would carry messages along the real sky, not the printed shortcuts.", "Luma would listen for the bell. Bramble would compare the older maps. Pip and Molly would walk Mrs Barley's route to see whether a remembered journey could be made usable again.", "Juniper arrived while they were assigning the tasks.", "He took one look at the maps and sighed.", "“I had intended to spend the evening doing almost nothing.”", "“You still can,” Molly said. “In a particularly helpful place.”", "She asked him to watch the ordinary river crossing and guide anyone who found it.", "The cat considered this.", "“Do I get a sign?”", "Pip gave him a blank leaf.", "Juniper wrote REAL BRIDGE. REALLY.", "Molly approved the clarity.", "As they left, Luma touched her shoulder with one soft wing.", "“Don't accept a way home just because it knows your name.”", "Molly looked at the black door on the map.", "“I won't,” she said.", "This was a promise she intended to keep."]}, {"chapter": 5, "chapterTitle": "The House Behind the Fold", "paragraphs": ["Mrs Barley was waiting with a basket of pear cakes.", "“If you can't get the path back,” she said, “we may as well eat while discussing it.”", "Molly liked her.", "Pip stood at the beginning of the paper fan and read the mole's description aloud.", "Three stones.", "Fallen pear tree.", "Parcel-dropping bend.", "Nothing happened.", "Molly sniffed the ground beside the first silver crease.", "Old fruit. Wet bark. A faint trace of mole.", "“The description isn't the walk,” she said.", "They would need to find the actual things.", "She led Pip through a gap between the first two folds. The world became strangely narrow. A branch looked flat until she passed it, then opened into three dimensions behind her.", "Pip held a guide vine tied to the real gatepost.", "“Keep something ordinary connected,” he murmured.", "Ahead, three stones lay in the grass.", "One had a chipped white edge.", "Molly touched it with her nose.", "The nearest paper crease loosened.", "From the cottage window, Mrs Barley gave a delighted shout.", "Pip made the first mark on a fresh leaf.", "Not copied from an atlas.", "Drawn because his feet were actually there."]}, {"chapter": 5, "chapterTitle": "The House Behind the Fold", "paragraphs": ["At the fallen pear tree, the route divided into seven identical-looking gaps.", "Each had a silver arrow. Each promised the cottage lay just beyond it.", "Molly sat down.", "Pip looked at her anxiously.", "“Thinking?”", "“Refusing to be hurried by signs.”", "She took off her sunglasses. Reflected moonlight had made the silver arrows appear brighter than the spaces around them.", "Without it, she could see a shallow hollow where the tree's old roots had lifted the ground.", "A parcel string lay caught on one branch.", "The real bend was behind the trunk, not beyond any of the arrows.", "She and Pip went round together.", "The guide vine tightened.", "Pip stopped immediately.", "They had nearly walked farther than the safe length they had agreed. The cottage sounded close enough to tempt them on.", "Molly backed up.", "“Fetch more vine,” she said.", "“We're nearly there.”", "“Yes. Let's remain nearly there until we can be properly there.”", "Pip returned along their marked route. Molly waited beside the chipped stone, making sure the connection remained visible.", "She disliked waiting in an uncertain place.", "She disliked the prospect of both of them becoming lost considerably more."]}, {"chapter": 5, "chapterTitle": "The House Behind the Fold", "paragraphs": ["While Pip was away, a paper bird landed on the fallen tree.", "Its wings carried tiny printed gardens. Its eyes were two precise dots.", "Mr Vellum's voice came from its folded beak.", "“You're spending a long time on a very short road.”", "Molly kept one paw beside the guide vine.", "“Perhaps it needs the attention.”", "“I could bring your Jim to you.”", "Every hair along her neck rose.", "“Could you?”", "“I have the road on your map.”", "“You have a drawing.”", "“A drawing can become a door.”", "“Not without an invitation.”", "The bird's printed eyes narrowed.", "“A clever little traveller.”", "Molly felt a familiar irritation.", "“Little isn't the useful part.”", "Mr Vellum offered an agreement. She would let his atlas use her route between the wood and the outside, and he would guarantee that she could always return home.", "Always was printed in exceptionally beautiful letters.", "Molly remembered the rules of the wood.", "“No.”", "The paper bird unfolded a fraction.", "“You should consider what that refusal might cost.”", "“I'm considering what your guarantee might.”", "It flew away just as Pip returned.", "Molly told him every word.", "Being frightened was not a reason to keep the frightening part secret."]}, {"chapter": 5, "chapterTitle": "The House Behind the Fold", "paragraphs": ["With the longer vine and Fern's help at the gatepost, they reached Mrs Barley's front step.", "The mole opened her door before Molly could knock.", "“I'd hug you,” she said, “but there's a measuring mouse underfoot.”", "Pip finished the last line of his hand-drawn map.", "The route behind them did not lose all its folds. But a narrow real path showed through from gatepost to doorstep, tied to three remembered places and one actual walk.", "Mrs Barley stepped onto it.", "The paper fan shivered.", "Her paw touched the chipped stone, then the old pear bark.", "The path grew a little wider.", "Nettle, arriving through the nearby drainage run, looked satisfied.", "“People are part of the anchor,” he said. “Not just the landmarks.”", "Molly accepted a pear cake.", "“That seems a useful thing for an atlas to know.”", "They escorted Mrs Barley to Fern's house, leaving her own door securely closed. The route remained fragile. Nobody needed to prove it by spending another hour trapped inside it.", "Pip rolled his new map with obvious care.", "For the first time since Molly arrived, he looked less like an apprentice borrowing confidence and more like a pathfinder making some of his own."]}, {"chapter": 5, "chapterTitle": "The House Behind the Fold", "paragraphs": ["The good news reached the Star Room first.", "The bad news was waiting underneath it.", "Mr Vellum's office now occupied the Milepost House, and its silver lines were tightening around the centre of the wood. Some real paths were still open. Others folded whenever a shortcut crossed them.", "Bramble spread Pip's successful route beside the oldest atlas.", "“If we connect enough real anchors before midnight, the bell can call the old ways back.”", "“And if we don't?” Molly asked.", "“The atlas becomes the only map the central paths recognise.”", "“Then nobody travels without him.”", "Luma nodded.", "Quill produced another paper agreement from his bundle.", "Molly's name appeared at the top.", "She had not signed it.", "Nor, on closer inspection, had anybody pretended she had. The space for her pawprint remained blank, surrounded by a neat oval of waiting silver ink.", "At the bottom stood a drawing of Jim's front door.", "Molly looked at it for a long moment.", "Then she put the paper face down.", "“Let's be very clear,” she said. “He doesn't get to make my home the price of everyone else's.”", "Pip placed his new map beside her paw.", "“Then we need a better route.”"]}, {"chapter": 6, "chapterTitle": "The Things a Map Cannot Own", "paragraphs": ["Rebuilding the old ways began with a surprising amount of conversation.", "Fern asked people which gate they actually used, which tree they sheltered under and which awkward turn they took because a neighbour enjoyed company.", "Nettle traced water that had travelled the same channels for years. Quill carried the descriptions overhead, checking each one with the person who had given it.", "Juniper sat beside his sign and prevented three confused squirrels from following a paper arrow into the river.", "He did not improve the experience by being modest about it.", "Molly and Pip carried the first completed route back to the central junction. Pip marked the chipped stone, the pear tree and the real cottage step on a broad leaf laid against the old milepost.", "A faint brown line appeared under the grass.", "“It's listening,” he said.", "“Then tell it the actual distance,” Molly replied. “Even if it isn't impressive.”", "The line curved, inconvenient and correct, around the trees.", "From the far end came Mrs Barley's voice thanking Fern for the tea.", "Not a perfect route. Not a fast route.", "A route with a person at each end and something real between them."]}, {"chapter": 6, "chapterTitle": "The Things a Map Cannot Own", "paragraphs": ["Mr Vellum addressed the market from the roof of his office.", "His paper birds carried his words in neat, identical voices.", "“Some residents are attempting to restore inefficient and potentially confusing routes. Please remain on the approved silver paths.”", "Molly watched a printed bird fold a tiny official-looking cap onto its head.", "“That's new,” she said.", "Bramble put a notice on the library door. It explained what they had measured, which real paths remained usable and which routes should not be attempted yet.", "No dramatic claims. No imitation authority.", "Quill read it, then asked whether he could copy it onto his empty labels.", "“Exactly,” Bramble said. “And say who checked it.”", "Within minutes, ordinary handwritten notices appeared beneath the collector's printed arrows.", "REAL ROUTE TO MARKET. CHECKED BY FERN AND NETTLE.", "PAPER BRIDGE NOT INSPECTED. USE THE OLD CROSSING.", "Molly looked at the disagreement between the signs.", "Mr Vellum's letters were more beautiful.", "The handwritten ones could tell you who had been there.", "Pip found another root connection beside the milepost. His map brightened.", "Then a paper bird landed close to his feet, carrying a folded note.", "Your missing route records are waiting inside.", "Pip looked towards the office door."]}, {"chapter": 6, "chapterTitle": "The Things a Map Cannot Own", "paragraphs": ["Molly did not see him go in.", "She had turned to help Fern free a barrow wheel from a silver crease. When she looked back, Pip's map tube lay beside the milepost.", "No Pip.", "The office door stood open.", "Molly called his name once. Then she stopped and listened.", "A small tapping came from somewhere inside the folds.", "Bramble reached the door before her and put his stick against the threshold. Its shadow went one way. The stick went another.", "“Not an ordinary entrance,” he said.", "Molly's stomach tightened.", "Mr Vellum stepped down from the roof.", "“The apprentice has entered a route still under construction.”", "“Let him out.”", "“He has misplaced the exit.”", "“You wrote it that way.”", "The fox said nothing.", "Molly wanted to bark so loudly the paper birds fell from the roof. She wanted to bite every silver crease she could reach.", "Instead she asked whether Pip could hear them.", "A faint voice answered from inside.", "“Yes.”", "“Are you hurt?”", "“No. But this room keeps becoming the room I just left.”", "Molly kept her eyes on the fox.", "“Stay where you are. We're finding the real way.”"]}, {"chapter": 6, "chapterTitle": "The Things a Map Cannot Own", "paragraphs": ["Mr Vellum placed the unsigned agreement on the threshold.", "“One pawprint,” he said. “Your friend leaves safely. Your own return becomes certain. A sensible exchange.”", "Molly looked at the oval of waiting ink.", "She understood suddenly why he preferred maps to conversations. On a map, he could make every question seem to have only the answers he provided.", "Pip's small voice came through the folded doorway.", "“Don't sign it.”", "“You don't have to make this easier for me,” Molly called.", "“Wasn't planning to.”", "Bramble moved close enough to speak quietly.", "“We can inspect the outside. The Milepost House existed before the office did.”", "Nettle arrived at the back corner, damp as usual and useful as ever.", "“The real cellar drain is still where it was. So is the wall.”", "Mr Vellum's tail shifted.", "For the first time, he looked uncertain about the ground beneath him.", "Molly did not sign.", "She also did not announce that refusing had solved the problem.", "They still had a frightened mouse to reach.", "She gave Pip's tube to Bramble, took a careful sniff of the ordinary stones and began walking around the house."]}, {"chapter": 6, "chapterTitle": "The Things a Map Cannot Own", "paragraphs": ["At the back wall, Nettle found an old ventilation opening.", "Through it came paper dust, cold mortar and a small, familiar scent of mouse.", "Molly put her nose against the grille.", "“Pip. Can you hear my voice from here?”", "“Yes. Lower down.”", "“Keep talking.”", "He described the room. Wooden shelf. Damp corner. A carved pear on an old storage chest. One real stone wall behind a curtain of printed doors.", "Nettle nodded.", "“Cellar. My grandfather repaired that drain.”", "The real stair lay beneath a mat of folded maps beside the office. Nobody could see it, but the top step smelled of worn stone and spilled oil.", "Molly nosed the edge of the mat.", "A silver arrow turned sharply away from her.", "She ignored it.", "Bramble held one end of the guide vine. Fern secured the other to the actual milepost.", "Molly placed her paw on the hidden step.", "It stayed beneath her.", "“Good,” she whispered. “You remember being a stair.”", "She moved down slowly, following Pip's voice instead of the printed doors.", "Above her, Mr Vellum said, very quietly, “That isn't on the plan.”"]}, {"chapter": 7, "chapterTitle": "An Apprentice Finds His Feet", "paragraphs": ["The cellar was much less mysterious than its entrances suggested.", "It contained storage shelves, an old chest, a broken broom and a small mouse who looked furious with himself.", "Molly reached him through a gap between two paper curtains.", "Pip put both paws around her muzzle.", "“I followed a message without checking.”", "“Yes.”", "“I thought the maps were there.”", "“I know.”", "“I knew better.”", "Molly waited until he looked at her.", "“Knowing better doesn't mean you never get caught. Let's do the next bit better.”", "They found the real wall together. Pip tied a scrap of vine to the actual stair rail, then made a tiny drawing of the cellar as it was, including the broken broom.", "“Why the broom?” Molly asked.", "“Because it's here. And the door on that wall isn't.”", "They walked out along the route she had just taken, leaving a real marker at each step.", "The paper curtains tried to offer seven alternative exits.", "Pip did not look at them.", "When he reached the open air, Fern gave him water. Bramble checked that he was unhurt.", "Nobody called him foolish.", "The fact that he was already doing it himself was quite sufficient."]}, {"chapter": 7, "chapterTitle": "An Apprentice Finds His Feet", "paragraphs": ["Mr Vellum stood beside the empty agreement.", "His precise face had acquired several extra creases.", "Molly faced him with Pip safely behind her.", "“You kept someone in a room so I'd give you a road.”", "“The room was—”", "“Real,” she said. “The exits were yours.”", "He folded the agreement, slowly.", "Bramble asked him to unlock the bell drawer.", "The fox looked towards the centre of his atlas, where thousands of silver lines had begun drawing themselves into a single knot.", "“I can't simply remove it now.”", "“Why?”", "“The bell is holding the borrowed names apart. If it leaves before the real routes are ready, the atlas folds them together.”", "Pip looked at the knot.", "“Then help us finish the anchors.”", "“I have finished my atlas.”", "“No,” Pip said. “You've made one place everything else has to pass through.”", "The words hung between them.", "From beneath the office, the real cellar route widened slightly, strengthened by the mouse who had just walked it.", "Mr Vellum heard the stone stair settle.", "For the first time, his beautifully printed certainty looked rather thin."]}, {"chapter": 7, "chapterTitle": "An Apprentice Finds His Feet", "paragraphs": ["They had enough anchors to begin returning the main paths.", "Not all of them.", "Quill's lists showed one missing cluster beyond the east orchard, where three households had accepted new routes and forgotten to keep copies of the old ones.", "The residents remembered arriving. They remembered home.", "They could not describe the walk between.", "Molly thought of her first view of the wood, when everything had been so extraordinary that she had scarcely noticed the ordinary turns.", "“Can they walk from the home end?” she asked.", "Nettle checked the remaining channels. One narrow run still reached the orchard bank from below.", "Too small for Bramble. Suitable for a vole with strong opinions about drains.", "“I'll take the guide line through,” he said. “Get them moving towards the real water.”", "Fern would wait at the orchard edge. Quill would carry messages over the folds.", "Molly stayed beside Pip while he marked the growing network on a fresh leaf.", "The drawings were uneven. One tree looked like a particularly anxious cabbage.", "“You can improve that later,” she said.", "“The tree?”", "“The drawing.”", "“Good. I haven't asked the tree's permission.”"]}, {"chapter": 7, "chapterTitle": "An Apprentice Finds His Feet", "paragraphs": ["In the Star Room's notes, Bramble found the final part of the bell's instructions.", "Each borrowed way had to be claimed by someone who could name its real beginning or end. The bell's note would carry that recognition along the prepared anchors.", "No single person could do it for everybody.", "Molly glanced at Luma. The moth gave a dry little smile.", "“We seem determined to relearn that.”", "Quill returned to the households with clear instructions. No shouting was necessary. When the bell sounded, they would say the name of the place they knew and touch something real at its edge.", "A doorstep. A garden gate. A chipped stone.", "Molly asked about people who could not reach theirs.", "“Then someone who shares that journey can answer with them,” Bramble said. “A way isn't a possession. It's a connection.”", "Pip put Mrs Barley's map on the old milepost. Its brown line joined Fern's garden route.", "Across the wood, small honest lines began answering one another.", "Mr Vellum watched from the office.", "His atlas contained more detail than all their leaf drawings together.", "It was beginning to look, nevertheless, like the map that understood less."]}, {"chapter": 7, "chapterTitle": "An Apprentice Finds His Feet", "paragraphs": ["The first real trouble came when Mr Vellum tried to tighten the silver knot.", "Perhaps he hoped to finish before they could stop him. Perhaps he simply did not know how to do anything except continue the work he had begun.", "Either way, the result was immediate.", "The paper bridge folded upwards. A section of market path curled across the river. The office doors started closing on one another.", "Molly grabbed Pip's satchel as he slid towards a new crease.", "Fern braced the guide vine. Bramble held the actual milepost with both paws.", "“Stop drawing!” Molly barked.", "Mr Vellum froze.", "A thin stream of water ran from the corner of the atlas.", "Salt water.", "Not the river. Not anything printed on the fox's maps.", "The black door on Molly's leaf shone through Pip's satchel.", "Mr Vellum stared at it.", "His paper ears flattened.", "Molly saw genuine fear before he could fold it neatly away.", "“What have you opened?” she asked.", "“I didn't open that.”", "The silver knot pulled tighter.", "From somewhere impossibly far below their feet came a slow sound like a clock being wound beneath the sea."]}, {"chapter": 8, "chapterTitle": "The Place Nobody Drew", "paragraphs": ["Bramble ordered everyone onto the ordinary stone around the Milepost House.", "The word ordered sounded strange in his voice. Nobody argued with it.", "Luma placed Molly's wet leaf map inside a dry bowl, separate from the collector's atlas. The water from its corner stopped reaching the silver knot.", "The folding slowed.", "Not stopped. Slowed enough to think.", "Molly turned to Mr Vellum.", "“The bell. Now.”", "He looked at the drawer.", "“My atlas will come apart.”", "“It needs to.”", "“You don't understand what it holds.”", "“Then tell us something true.”", "For a long moment, the fox said nothing.", "At last he unfolded a small inner pocket beside his shoulder.", "Inside lay a scrap of paper bearing the seven-pointed compass.", "Alder's mark.", "“He made me at this table,” Mr Vellum said. “Before the house had wheels. He said every traveller deserved to know a way back.”", "“And then?”", "“He took the Tide Road. He said he would return.”", "The fox's voice lost its tidy edges.", "“I kept collecting maps. I thought one of them must show where he went.”"]}, {"chapter": 8, "chapterTitle": "The Place Nobody Drew", "paragraphs": ["Molly looked at the little paper pocket.", "Alder's scrap had been folded and unfolded so often that its edges looked soft as cloth.", "She understood waiting for a voice. She understood wanting a way home so much that a bad offer could become tempting.", "She did not let either understanding excuse Pip's cellar.", "“You could have asked for help,” she said.", "“I am a collector.”", "“You're also someone who's lost.”", "Mr Vellum looked away.", "Bramble sat on the real doorstep.", "“I would have helped you search the library.”", "“You might have refused.”", "“Yes.”", "The fox's ears lifted slightly.", "“A person asking a question has to allow an answer,” Bramble said. “Even one he doesn't like.”", "Luma checked the remaining root connections. The final lantern-hour was nearly over. They could not hold a discussion until it became a replacement for action.", "Pip stepped forward.", "“Help us return the paths. Then you can ask about Alder.”", "“No promise that you'll find him?”", "“No.”", "The mouse's voice trembled, but the answer did not change.", "Mr Vellum looked from the false doorways to the ordinary stair Pip had used.", "Then he took out the drawer key."]}, {"chapter": 8, "chapterTitle": "The Place Nobody Drew", "paragraphs": ["The Waybell was small enough for Molly to hold between her paws.", "Brass, slightly dented, with a wooden handle polished by years of use. It was neither grand nor especially impressive.", "Mr Vellum had wrapped its clapper in a strip of blank paper.", "Luma asked before touching it. The bell gave a faint answering warmth.", "“Still itself,” she said.", "At the orchard, the final anchor had not yet connected.", "Quill circled overhead, waiting for Nettle's signal. Fern held the guide line at the real edge of the wood.", "“We need another few moments,” Bramble said.", "The atlas began folding again.", "Without the bell in its drawer, its names were slipping together. The office roof bent. Paper birds tumbled into the awning and unfolded into harmless squares.", "Mr Vellum stepped across the moving pages and caught two silver threads between his paws.", "“What are you doing?” Molly called.", "“Holding the borrowed ways apart.”", "“Can you?”", "“Not for long.”", "He did not say always. He did not offer a guarantee.", "Molly almost smiled despite everything.", "A less impressive answer.", "An enormously more useful one."]}, {"chapter": 8, "chapterTitle": "The Place Nobody Drew", "paragraphs": ["Quill's red waistcoat flashed above the orchard.", "Once. Twice.", "Wait.", "Molly held the bell still.", "Below the folding paths, Nettle reached the three stranded households. They had followed his voice to the real water, touching the rough stones of a channel older than any silver sign.", "One rabbit remembered the smell of garlic at the far bank. Another remembered an apple root that caught her barrow wheel.", "Their feet found the ordinary ground.", "Fern saw the guide line move and knelt beside the returning path.", "Quill turned in the sky.", "Three slow circles.", "Ready.", "Bramble read the connections from Pip's map. Every main branch answered.", "Luma unwound the blank paper from the clapper.", "The bell's first tiny movement made Mr Vellum flinch, but he held the threads.", "Molly looked at him.", "“You'll have to let go when it rings.”", "“I know.”", "She believed him this time.", "The real sky above the wood deepened to midnight.", "For one breath, even the impatient leaves seemed to wait.", "Pip laid his paw beside hers on the handle.", "Together, they rang the Waybell."]}, {"chapter": 8, "chapterTitle": "The Place Nobody Drew", "paragraphs": ["Its note was quiet.", "Molly had expected something large enough to shake the trees. Instead it sounded like a small true thing being heard in many places at once.", "Mrs Barley touched her front step and spoke the name of her cottage.", "Fern named the garden.", "Juniper, beside the ordinary bridge, said, “The bridge,” then added, “The real one,” because accuracy was important.", "Across the wood, voices answered from gates, paths, windows and the edges of fields.", "The note travelled along roots, water, worn stones and the leaf maps their friends had drawn.", "Silver arrows loosened.", "Folded paths opened into distances that were sometimes longer, occasionally muddier and unmistakably their own.", "Mr Vellum released the threads.", "The central knot came apart.", "His atlas lifted like a great startled bird, then separated into hundreds of little maps, each seeking the person who had lent it.", "The office walls folded gently inward. The real Milepost House remained behind them, ordinary stone under stars.", "Mr Vellum stepped onto its doorstep.", "For a moment he looked smaller without his shortcuts.", "Then Pip touched the real ground beside him.", "“You're still here,” the mouse said.", "The fox looked down.", "“So I am.”"]}, {"chapter": 9, "chapterTitle": "The Long Way Round", "paragraphs": ["Returning the paths did not finish the evening's work.", "It began the checking.", "Nettle inspected every channel the silver lines had crossed. Fern made sure the orchard households could reach their homes without help. Quill delivered maps back to owners who had already received them and claimed this demonstrated a particularly thorough service.", "Bramble asked him to make a refund list.", "The jackdaw sighed.", "“Less profitable thoroughness.”", "“More useful,” Molly said.", "The paper bridge had become a tidy stack of dry maps beside the real bank. Juniper checked the ordinary crossing, found it sound and sat under his sign looking deeply satisfied.", "Molly went with Pip to Mrs Barley's cottage.", "The mole walked them round the pear tree herself, slowly and with great pride.", "“I shall never complain about this bend again.”", "Molly raised one eyebrow.", "“Well,” Mrs Barley said, “not this week.”", "Pip laughed.", "On the way back, he took out his notebook.", "He did not straighten the awkward bend.", "He drew the pear tree properly, the chipped stone beside it and the little place where a traveller could stop to catch her breath."]}, {"chapter": 9, "chapterTitle": "The Long Way Round", "paragraphs": ["Mr Vellum stayed at the Milepost House while the borrowed-route claims were checked.", "He was not invited to continue selling shortcuts.", "Nor was he driven into the river, burned, torn up or permitted to announce that helping at the last moment had cancelled the rest.", "Bramble explained what needed repairing. Quill gave him the names of the people affected. Nettle provided a damp, extremely detailed description of the inspection route that had ended at a wall.", "Pip stood beside Molly as the fox read it.", "“I shouldn't have kept you in that cellar,” Mr Vellum said.", "“No,” Pip replied.", "“I am sorry.”", "Pip nodded, but did not pretend trust had returned merely because the apology was accurate.", "The fox accepted that with visible difficulty.", "Molly thought it was a good beginning precisely because it was not a comfortable one.", "Luma offered him a dry seat beneath the east-bank shelter while Bramble searched for Alder's remaining records.", "“An invitation,” she said. “To sit. Not to manage the bank.”", "Mr Vellum gave a small, creased smile.", "“Understood.”", "He looked at the ordinary path leading there.", "“Could someone show me the way?”"]}, {"chapter": 9, "chapterTitle": "The Long Way Round", "paragraphs": ["Pip showed him.", "Molly followed at a respectful distance, near enough to help and far enough not to turn the walk into an inspection.", "They passed Fern's garden, the repaired junction and a small patch of moonflowers that had never required a label to know what it was doing.", "Mr Vellum paused at each turn.", "“May I draw this?” he asked.", "Pip considered.", "“Your own walk, yes. Ask before marking someone's private door.”", "The fox took out a plain sheet.", "His first drawing was beautiful.", "His second included a place to rest.", "Molly noticed.", "At the shelter, Luma had placed a dry cushion beside the flowers. The fox sat on it carefully, as though an ordinary welcome might contain a hidden agreement.", "There was none.", "He looked almost more troubled by that.", "Pip returned to Molly.", "“You didn't have to guide him,” she said.", "“I know.”", "“Are you all right?”", "He looked at his paws.", "“I wanted him to ask. Properly.”", "Molly touched his shoulder with her nose.", "Then they took the long way back to the library, because the long way included the baker and they had earned a sensible discussion about supper."]}, {"chapter": 9, "chapterTitle": "The Long Way Round", "paragraphs": ["At the Leaf Library, Bramble spread the evening's new maps on the desk.", "Some disagreed about distances. A few trees appeared in different places depending on which side of the path the walker had been. One route contained a large warning about a grumpy goose.", "“That goose is relevant,” Fern said.", "“I've filed it under local conditions,” Bramble replied.", "Pip looked embarrassed by his anxious-cabbage tree.", "Bramble placed it beside the oldest atlas.", "“A useful record.”", "“It's untidy.”", "“It's honest about where you went.”", "Molly settled on a cushion while the others ate. The library smelled of paper, apples, badger and a great many relieved people.", "Her cream bow had come loose. Pip retied it while she held still with considerable effort.", "“Your map got us out,” she told him.", "“Your nose got us in.”", "“Several people helped with the middle.”", "“We should put them on it.”", "So Pip added the names of the walkers beside each checked route.", "Not owners.", "People who had been there, ready to explain what they knew.", "Outside, the little path bells rang the half-hour together.", "This time, all of them answered."]}, {"chapter": 9, "chapterTitle": "The Long Way Round", "paragraphs": ["Molly remembered Jim.", "The relief in the library had made it dangerously easy to forget the folding minute waiting beside the park fountain.", "She stood up.", "“I should go.”", "Pip looked towards the window. The moon was still above the branches. Moonset had not reached the gate, but it would not wait indefinitely.", "Bramble packed two oatcakes into a little leaf wrapper.", "“For the ordinary part of the journey.”", "Luma checked the gate path. Clear, blue-edged and properly invited.", "Juniper arrived with his sign under one arm.", "“I've left the bridge where I found it,” he said. “You're welcome.”", "Molly thanked everyone, including him, which seemed to take some of the enjoyment out of his remark.", "Then she went to collect her map from the dry bowl.", "The bowl was no longer dry.", "Salt water shone around the silver-green leaf. The little black door had acquired a handle.", "Underneath it, the words YOU ARE EXPECTED had vanished.", "In their place stood a new line.", "IF YOU CHOOSE TO COME, BRING THE ONE WHO HEARS THE ROADS.", "Pip stared.", "Molly looked up at Bramble.", "“Please tell me that's a normal end-of-evening message.”", "He did not."]}, {"chapter": 10, "chapterTitle": "The Door After Midnight", "paragraphs": ["They did not touch the handle on the map.", "Molly was quite firm about that.", "“We've had a full evening of instructions from paper,” she said. “We're going to ask the questions first.”", "Luma examined the new line without letting her antenna meet the wet ink.", "“This is an invitation,” she said. “A conditional one. It isn't pretending you've already agreed.”", "“From whom?”", "The moth shook her head.", "Bramble compared the writing with Alder's old notes. The compass mark matched. Several letter shapes matched.", "That was evidence, not proof.", "Mr Vellum, fetched from the shelter, looked at the map and took a careful step back.", "“I copied his compass onto some of my papers,” he admitted. “So people would trust the work.”", "Bramble gave him a long look.", "“But not that,” the fox added. “Not the door. I couldn't draw it if I wanted to.”", "Molly sniffed the water.", "Deep sea. Cold stone. A distant trace of pine-marten fur so old she could not be certain it was there.", "Beneath all of it came a sound she had never smelled before.", "An enormous road, waiting underwater."]}, {"chapter": 10, "chapterTitle": "The Door After Midnight", "paragraphs": ["Bramble found a letter in the oldest observatory file.", "It had been delivered after Alder vanished and placed among records no one had quite known how to classify.", "Molly looked at him.", "“I know,” he said. “We're changing that system.”", "The letter mentioned a harbour below the horizon, a lighthouse that shone into places instead of across water, and a route that could not be followed by eyes alone.", "Alder had underlined the final instruction.", "If the road reaches back, keep the gate on your side of the threshold. Do not let the tide choose for you.", "Pip read it twice.", "“What does keeping a gate mean?”", "“Leaving a real way back,” Luma said.", "Molly thought about guide vines, honest maps and a small mouse waiting at the other end of a route.", "“That part I understand.”", "At the bottom of the letter, beside the compass stamp, Alder had drawn three little shapes.", "A bell.", "A shell.", "A small open paw.", "No explanation followed.", "Juniper leaned over the page.", "“Poor labelling,” he said.", "Bramble, who would normally have defended a historic document, nodded with feeling."]}, {"chapter": 10, "chapterTitle": "The Door After Midnight", "paragraphs": ["A soft knock came from the library wall.", "Everyone turned towards it.", "The knock came again, just beside the message cabinet.", "There had never been a door there. Bramble was very clear on that point. He had catalogued every wall in the library after a cupboard once developed an unexpected opinion about location.", "Now a narrow black outline appeared in the bark.", "Molly's map floated an inch above the bowl.", "A drop of salt water struck the floor.", "“Back,” Luma said quietly.", "They moved behind the actual desk, leaving the clear space around the new threshold empty.", "Bramble brought a sand tray from the repair room to catch the trickling water. Nettle checked that the floor channels were open.", "Nobody wanted a mysterious ocean reaching the lower shelves.", "The outline darkened into a frame.", "A handle formed.", "On the map, the invitation waited without changing.", "Molly looked at the path to the real library door, then at the moon through the window.", "Her way home remained open.", "That mattered.", "She was not being trapped into another choice.", "Something beyond the wall was asking one of her."]}, {"chapter": 10, "chapterTitle": "The Door After Midnight", "paragraphs": ["The black door opened the width of a mouse's paw.", "Nobody had turned its handle.", "Beyond it lay a sea beneath an impossible sky. The stars shone below the water. An enormous moon hung upside down, its reflection reaching upwards towards darkness.", "Far away, a lighthouse gave one slow pulse.", "Pip gripped Molly's neckerchief.", "Not to stop her.", "To make sure they both knew where the other was.", "A pale shell slid across the threshold into Bramble's sand tray.", "The door stopped opening.", "Luma listened, head tilted.", "“No further invitation has been accepted. This is only a message.”", "Bramble used wooden tongs to lift the shell onto a dry cloth.", "Molly was pleased that the library kept such practical things. You never knew when history might require tongs.", "The shell held Alder's compass mark.", "Beside it was a tiny dark pawprint.", "Mr Vellum leaned closer, then stopped.", "“I know that mark.”", "“Alder's?” Pip asked.", "The fox's paper ears slowly lowered.", "“No,” he whispered.", "The shell gave a small, clear click.", "From inside came the sound of someone breathing."]}, {"chapter": 10, "chapterTitle": "The Door After Midnight", "paragraphs": ["The voice in the shell was faint, hurried and unmistakably real.", "“If this reaches Moonflower Wood, the Tide Road is open again. Don't follow the lighthouse. It has learned to shine in the wrong direction.”", "Bramble went very still.", "“Alder?”", "Static crackled like sand moving over glass.", "Then the voice returned.", "“I thought I was drawing a way out. Something else was drawing a way in.”", "Molly looked through the narrow door.", "Out on the impossible sea, the lighthouse pulsed again.", "A dark shape moved beneath its upside-down reflection.", "The shell warmed against the cloth.", "“Find the harbour with no shore,” the voice whispered. “And whatever you do, keep your own way home.”", "The message ended.", "For a moment nobody spoke.", "Then Pip opened a fresh leaf and placed it on the real library floor.", "“One end here,” he said.", "Molly put her paw beside his.", "“Questions first. A proper plan. Everybody gets a choice.”", "Bramble nodded. Luma folded her wings. Juniper sighed as though an extremely comfortable evening had been stolen from him again.", "Beyond the threshold, something knocked from the other side of the sea.", "Once.", "Twice.", "Then a voice that was not Alder's said, very softly:", "“At last. The little dog has found the door.”", "TO BE CONTINUED"]}];
